package com.yigongbao.backup.job;

import com.baomidou.mybatisplus.core.toolkit.Wrappers;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.dao.DuplicateKeyException;
import java.time.LocalDateTime;
import java.util.List;
import java.util.UUID;

/** 基于条件更新、租约和 fencing token 的多实例持久化任务协调器。 */
@Service @RequiredArgsConstructor
public class PersistentJobCoordinator {
 private final JobMapper mapper;
 public JobEntity create(String type,String key,long actor){return create(type,key,actor,"{}");}
 public JobEntity create(String type,String key,long actor,String config){JobEntity j=new JobEntity();j.setJobNo(UUID.randomUUID().toString());j.setJobType(type);j.setStatus("CREATED");j.setIdempotencyKey(key);j.setPriority(0);j.setProgressCurrent(0L);j.setProgressTotal(0L);j.setConfigSnapshotJson(config==null?"{}":config);j.setRequestedBy(actor);j.setRequestedAt(LocalDateTime.now());j.setFencingToken(0L);j.setRetryCount(0);j.setCancelRequested(false);try{mapper.insert(j);return j;}catch(DuplicateKeyException duplicate){JobEntity existing=mapper.selectOne(Wrappers.<JobEntity>lambdaQuery().eq(JobEntity::getIdempotencyKey,key).last("limit 1"));if(existing!=null)return existing;throw duplicate;}}
 public JobEntity retry(long id,long actor){JobEntity old=required(id);if(!"FAILED".equals(old.getStatus())&&!"CANCELLED".equals(old.getStatus()))throw new IllegalStateException("只能重试失败或已取消任务");String key="retry-of:"+old.getId()+":"+(old.getRetryCount()==null?0:old.getRetryCount());return create(old.getJobType(),key,actor,old.getConfigSnapshotJson());}
 public JobEntity claimNext(String owner,long lease){LocalDateTime now=LocalDateTime.now();List<JobEntity> list=mapper.selectList(Wrappers.<JobEntity>lambdaQuery().eq(JobEntity::getStatus,"CREATED").and(w->w.isNull(JobEntity::getNextRetryAt).or().le(JobEntity::getNextRetryAt,now)).orderByDesc(JobEntity::getPriority).orderByAsc(JobEntity::getId).last("limit 10"));for(JobEntity j:list){try{return claim(j.getId(),owner,lease);}catch(IllegalStateException ignored){}}return null;}
 public JobEntity claim(long id,String owner,long lease){if(owner==null||owner.isBlank()||lease<=0)throw new IllegalArgumentException("租约参数非法");JobEntity j=required(id);LocalDateTime now=LocalDateTime.now();boolean available="CREATED".equals(j.getStatus())||("RUNNING".equals(j.getStatus())&&j.getLeaseUntil()!=null&&!j.getLeaseUntil().isAfter(now));if(!available)throw new IllegalStateException("任务不可领取");int rows=mapper.update(null,Wrappers.<JobEntity>lambdaUpdate().eq(JobEntity::getId,id).eq(JobEntity::getVersion,j.getVersion()).eq(JobEntity::getStatus,j.getStatus()).set(JobEntity::getStatus,"RUNNING").set(JobEntity::getLeaseOwner,owner).set(JobEntity::getLeaseUntil,now.plusSeconds(lease)).set(JobEntity::getHeartbeatAt,now).set(JobEntity::getFencingToken,value(j.getFencingToken())+1).set(JobEntity::getStartedAt,j.getStartedAt()==null?now:j.getStartedAt()));if(rows!=1)throw new IllegalStateException("任务已被其他执行器领取");return required(id);}
 public void heartbeat(long id,String owner,long token,long lease){LocalDateTime now=LocalDateTime.now();requireUpdated(apply(guarded(id,owner,token).gt(JobEntity::getLeaseUntil,now).set(JobEntity::getLeaseUntil,now.plusSeconds(lease)).set(JobEntity::getHeartbeatAt,now)));}
 public void safePoint(long id,String owner,long token,String step,long progress){JobEntity j=required(id);validate(j,owner,token);if(Boolean.TRUE.equals(j.getCancelRequested())){requireUpdated(apply(guarded(id,owner,token).set(JobEntity::getStatus,"CANCELLED").set(JobEntity::getFinishedAt,LocalDateTime.now()).set(JobEntity::getLeaseOwner,null).set(JobEntity::getLeaseUntil,null)));throw new JobCancelledException("任务已在安全点取消");}requireUpdated(apply(guarded(id,owner,token).set(JobEntity::getCurrentStep,step).set(JobEntity::getProgressCurrent,Math.max(progress,0)).set(JobEntity::getHeartbeatAt,LocalDateTime.now())));}
 public void succeed(long id,String owner,long token){requireUpdated(apply(guarded(id,owner,token).eq(JobEntity::getCancelRequested,false).set(JobEntity::getStatus,"SUCCEEDED").set(JobEntity::getFinishedAt,LocalDateTime.now()).set(JobEntity::getLeaseOwner,null).set(JobEntity::getLeaseUntil,null)));}
 public void storeResult(long id,String owner,long token,String resultJson){requireUpdated(apply(guarded(id,owner,token).set(JobEntity::getResultJson,resultJson)));}
 public void failOrRetry(long id,String owner,long token,int maxRetries,Throwable failure){JobEntity j=required(id);validate(j,owner,token);int retry=(j.getRetryCount()==null?0:j.getRetryCount())+1;boolean again=retry<=maxRetries&&!Boolean.TRUE.equals(j.getCancelRequested());String message=failure==null||failure.getMessage()==null?"任务执行失败":failure.getMessage();if(message.length()>1000)message=message.substring(0,1000);var u=guarded(id,owner,token).set(JobEntity::getRetryCount,retry).set(JobEntity::getFailureCode,failure==null?"JOB_FAILED":failure.getClass().getSimpleName()).set(JobEntity::getFailureMessage,message).set(JobEntity::getLeaseOwner,null).set(JobEntity::getLeaseUntil,null);if(again){long delay=Math.min(300L,1L<<Math.min(retry-1,8));u.set(JobEntity::getStatus,"CREATED").set(JobEntity::getNextRetryAt,LocalDateTime.now().plusSeconds(delay));}else{u.set(JobEntity::getStatus,Boolean.TRUE.equals(j.getCancelRequested())?"CANCELLED":"FAILED").set(JobEntity::getFinishedAt,LocalDateTime.now());}requireUpdated(apply(u));}
 public void requestCancel(long id){int rows=mapper.update(null,Wrappers.<JobEntity>lambdaUpdate().eq(JobEntity::getId,id).in(JobEntity::getStatus,"CREATED","RUNNING","PAUSED").set(JobEntity::getCancelRequested,true));if(rows!=1)throw new IllegalStateException("任务不可取消");}
 public int recoverExpired(){LocalDateTime now=LocalDateTime.now();List<JobEntity> list=mapper.selectList(Wrappers.<JobEntity>lambdaQuery().eq(JobEntity::getStatus,"RUNNING").isNotNull(JobEntity::getLeaseUntil).le(JobEntity::getLeaseUntil,now));int count=0;for(JobEntity j:list){int retry=(j.getRetryCount()==null?0:j.getRetryCount())+1;int rows=mapper.update(null,Wrappers.<JobEntity>lambdaUpdate().eq(JobEntity::getId,j.getId()).eq(JobEntity::getVersion,j.getVersion()).eq(JobEntity::getStatus,"RUNNING").le(JobEntity::getLeaseUntil,now).set(JobEntity::getStatus,"CREATED").set(JobEntity::getLeaseOwner,null).set(JobEntity::getLeaseUntil,null).set(JobEntity::getNextRetryAt,now).set(JobEntity::getRetryCount,retry).set(JobEntity::getFailureCode,"LEASE_EXPIRED").set(JobEntity::getFailureMessage,"执行器租约过期，等待恢复"));if(rows==1)count++;}return count;}
 private com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper<JobEntity> guarded(long id,String owner,long token){return Wrappers.<JobEntity>lambdaUpdate().eq(JobEntity::getId,id).eq(JobEntity::getStatus,"RUNNING").eq(JobEntity::getLeaseOwner,owner).eq(JobEntity::getFencingToken,token);}
 private int apply(com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper<JobEntity> update){return mapper.update(null,update);}
 private JobEntity required(long id){JobEntity j=mapper.selectById(id);if(j==null)throw new IllegalArgumentException("任务不存在");return j;}
 private static long value(Long n){return n==null?0:n;} private static void requireUpdated(int n){if(n!=1)throw new IllegalStateException("租约或 fencing token 无效");}
 private static void validate(JobEntity j,String owner,long token){if(!"RUNNING".equals(j.getStatus())||!owner.equals(j.getLeaseOwner())||value(j.getFencingToken())!=token)throw new IllegalStateException("租约或 fencing token 无效");}
}
